<script setup lang="ts">
import { ref } from 'vue'
const { data: me, error: profileError, pending: profilePending, refresh: refreshProfile } = await useFetch<{ id: string; email: string; display_name: string; role: string }>('/api/me')
const { refresh: refreshAccount, forget } = useAccount()
const { data: requests, refresh: refreshRequests, error: requestsError, pending: requestsPending } = await useFetch<{ representatives: Array<{ id: string; company: string; status: string; created_at: string }> }>('/api/me/requests')
const displayName = ref(me.value?.display_name || '')
const representativeCompany = ref('')
const representativeEvidence = ref('')
const password = ref('')
const confirmation = ref('')
const message = ref('')
const error = ref('')
const busy = ref(false)
const ready = ref(false)
const activeAction = ref<'profile' | 'representative' | 'delete'>('profile')
const feedback = ref<HTMLElement | null>(null)
watch([message, error], async () => { await nextTick(); feedback.value?.focus() })
watch(me, value => { if (value) displayName.value = value.display_name }, { immediate: true })
onMounted(() => { ready.value = true })
const save = async () => { if (!ready.value || busy.value) return; activeAction.value = 'profile'; busy.value = true; error.value = ''; message.value = ''; try { await $fetch('/api/me/profile', { method: 'PATCH', body: { display_name: displayName.value } }); await refreshAccount(); message.value = 'Nama akun berhasil diperbarui.' } catch (e: unknown) { error.value = requestMessage(e, 'Pengaturan belum tersimpan.') } finally { busy.value = false } }
const removeAccount = async () => { if (!ready.value || busy.value) return; if (!window.confirm('Akun dan seluruh kontribusimu akan dihapus permanen. Lanjutkan?')) return; activeAction.value = 'delete'; busy.value = true; error.value = ''; message.value = ''; try { await $fetch('/api/me/delete', { method: 'POST', body: { password: password.value, confirmation: confirmation.value } }); forget(); await navigateTo('/?status=account-deleted', { replace: true }) } catch (e: unknown) { error.value = requestMessage(e, 'Akun belum berhasil dihapus.') } finally { busy.value = false } }
function requestMessage(error: unknown, fallback: string) { if (error && typeof error === 'object' && 'data' in error && error.data && typeof error.data === 'object' && 'statusMessage' in error.data && typeof error.data.statusMessage === 'string') return error.data.statusMessage; return fallback }
const requestRepresentative = async () => { if (!ready.value || busy.value) return; activeAction.value = 'representative'; busy.value = true; error.value = ''; message.value = ''; try { await $fetch('/api/me/company-representative', { method: 'POST', body: { company_id: representativeCompany.value, evidence: representativeEvidence.value } }); message.value = 'Permintaan verifikasi masuk antrean moderator.'; representativeEvidence.value = ''; await refreshRequests() } catch (cause: unknown) { error.value = requestMessage(cause, 'Permintaan verifikasi belum berhasil dikirim.') } finally { busy.value = false } }
useSeoMeta({ title: 'Pengaturan akun — KerjaGimana', robots: 'noindex,nofollow' })
</script>
<template><section class="app-page"><div class="page-shell"><header class="page-heading"><h1>Pengaturan akun</h1><p>Atur nama tampilan, kelola verifikasi, atau hapus data akunmu.</p></header><nav class="dashboard-nav" aria-label="Navigasi dashboard"><NuxtLink to="/dashboard">Ringkasan</NuxtLink><NuxtLink to="/dashboard/review">Kontribusi saya</NuxtLink><NuxtLink to="/dashboard/pengaturan">Pengaturan</NuxtLink></nav><UiCard class="dashboard-panel settings-panel"><h2>Profil</h2><p class="field-hint">Email akun: {{ me?.email }}</p><LoadError v-if="profileError" message="Profil belum bisa dimuat." :retrying="profilePending" @retry="refreshProfile()" /><form v-else class="stack-form" @submit.prevent="save"><label>Nama tampilan<UiInput v-model="displayName" required maxlength="60" autocomplete="nickname" /></label><UiButton type="submit" class="button button-red" :disabled="busy || !ready">Simpan perubahan</UiButton></form><p v-if="activeAction === 'profile' && (message || error)" ref="feedback" tabindex="-1" class="notice" :class="{ 'notice-error': error }" :role="error ? 'alert' : 'status'">{{ error || message }}</p></UiCard><section class="dashboard-panel settings-panel"><h2>Verifikasi wakil perusahaan</h2><p class="field-hint">Kirim bukti kewenangan. Moderator memeriksa permintaan sebelum perusahaan dapat mengirim tanggapan resmi.</p><form class="stack-form" @submit.prevent="requestRepresentative"><CompanyPicker v-model="representativeCompany" hint="Pilih perusahaan yang kamu wakili." /><label>Bukti kewenangan<textarea v-model="representativeEvidence" required minlength="30" maxlength="2000" rows="4" placeholder="Jelaskan kanal resmi atau dokumen yang dapat diperiksa moderator."></textarea></label><button class="button button-outline" :disabled="busy || !ready">Kirim permintaan verifikasi</button></form><p v-if="activeAction === 'representative' && (message || error)" ref="feedback" tabindex="-1" class="notice" :class="{ 'notice-error': error }" :role="error ? 'alert' : 'status'">{{ error || message }}</p><LoadError v-if="requestsError" message="Status verifikasi belum bisa dimuat." :retrying="requestsPending" @retry="refreshRequests()" /><div v-else-if="requests?.representatives.length" class="contribution-list representative-list"><article v-for="request in requests.representatives" :key="request.id" class="contribution-row"><div><strong>{{ request.company }}</strong><p>Permintaan dikirim {{ new Date(request.created_at).toLocaleDateString('id-ID') }}</p></div><span class="status-pill" :data-status="request.status">{{ request.status === 'verified' ? 'Terverifikasi' : request.status === 'pending' ? 'Menunggu tinjauan' : 'Ditolak' }}</span></article></div></section><section class="danger-panel"><h2>Hapus akun</h2><p>Akun dan kiriman terkait akan dihapus. Tindakan ini tidak dapat dibatalkan.</p><form class="stack-form" @submit.prevent="removeAccount"><label>Kata sandi saat ini<input v-model="password" type="password" required autocomplete="current-password"></label><label>Ketik <strong>HAPUS AKUN</strong> untuk mengonfirmasi<input v-model="confirmation" required autocomplete="off"></label><button class="button button-outline" :disabled="busy || !ready">Hapus akun dan kontribusi</button></form><p v-if="activeAction === 'delete' && error" ref="feedback" tabindex="-1" class="notice notice-error" role="alert">{{ error }}</p></section></div></section></template>
